using namespace std;

const int MAXN = 66;

int r, c, n;
string s;
long long comb[MAXN][MAXN];

int cnt_a[MAXN], cnt_b[MAXN];
vector<long long> partial[MAXN], partial_zero[MAXN];

void precompute_combinations() {
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
}

long long calculate_differences(int conf, int a_before, int b_before) {
    long long total_diff = 0;
    for (int i = 0; i <= c; ++i) {
        if (conf & (1 << i)) {
            b_before++;
            long long aux1 = comb[b_before - 1][r - 1];
            long long aux2 = comb[n - b_before][r] - comb[a_before][r];
            total_diff -= aux1 * aux2;
        } else {
            a_before++;
            long long aux1 = comb[a_before - 1][r - 1];
            long long aux2 = comb[n - a_before][r] - comb[b_before][r];
            total_diff += aux1 * aux2;
        }
    }
    return total_diff;
}

bool validate_conf(int conf) {
    for (int i = 0; i <= c; ++i) {
        if (s[2 * r + c + i] == 'A' && ((conf >> i) & 1) == 1) return false;
        if (s[2 * r + c + i] == 'B' && ((conf >> i) & 1) == 0) return false;
    }
    return true;
}

void process_second_part() {
    int total_conf = 1 << (c + 1);
    for (int conf = 0; conf < total_conf; ++conf) {
        int b_count = __builtin_popcount(conf);
        int a_count = c + 1 - b_count;
        if (validate_conf(conf))
            partial[a_count].push_back(calculate_differences(conf, r + c - a_count, r + c - b_count));
        else
            partial_zero[a_count].push_back(calculate_differences(conf, r + c - a_count, r + c - b_count));
    }
    for (int i = 0; i <= c + 1; ++i) {
        sort(partial[i].begin(), partial[i].end());
        sort(partial_zero[i].begin(), partial_zero[i].end());
    }
}

long long get_coefficient(int conf) {
    int i;
    for (i = 0; i <= c; ++i) {
        if ( ((conf >> i) & 1) != (conf & 1) ) break;
    }
    for (int j = i; j <= c; ++j) {
        if (s[2 * r - 1 + j] == 'A' && (((conf >> j) & 1) == 1)) return 0;
        if (s[2 * r - 1 + j] == 'B' && (((conf >> j) & 1) == 0)) return 0;
    }
    int setA = r - 1 + ( (conf & 1) == 0 ? i : 0 );
    int setB = r - 1 + ( (conf & 1) == 1 ? i : 0 );
    if (setA < cnt_a[2 * r - 2 + i]) return 0;
    if (setB < cnt_b[2 * r - 2 + i]) return 0;
    int total = setA + setB - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i];
    return comb[total][setA - cnt_a[2 * r - 2 + i]];
}

void update_answer(pair<long long, long long>& answer, pair<long long, long long> current) {
    if (current.first < 0) current.first = -current.first;
    if (answer.first > current.first) {
        answer = current;
    } else if (answer.first == current.first) {
        answer.second += current.second;
    }
}

long long count_occurrences(const vector<long long>& data, long long val) {
    auto lower_it = lower_bound(data.begin(), data.end(), val);
    auto upper_it = upper_bound(data.begin(), data.end(), val);
    return upper_it - lower_it;
}

long long solve_first_part() {
    int total_conf = 1 << (c + 1);
    pair<long long, long long> answer = {1LL << 60, 0};
    for (int conf = 0; conf < total_conf; ++conf) {
        int b_count = __builtin_popcount(conf);
        int a_count = c + 1 - b_count;
        long long act = calculate_differences(conf, r - 1, r - 1);
        long long coef = get_coefficient(conf);
        auto it = lower_bound(partial[c + 1 - a_count].begin(), partial[c + 1 - a_count].end(), -act);
        if (it != partial[c + 1 - a_count].end()) {
            long long val = *it + act;
            if (abs(val) <= answer.first) {
                long long count_coef = count_occurrences(partial[c + 1 - a_count], *it);
                update_answer(answer, {abs(val), coef * count_coef});
            }
        }
        if (it != partial[c + 1 - a_count].begin()) {
            --it;
            long long val = *it + act;
            if (abs(val) <= answer.first) {
                long long count_coef = count_occurrences(partial[c + 1 - a_count], *it);
                update_answer(answer, {abs(val), coef * count_coef});
            }
        }
        // Zero coefficient branch
        long long zero_coef = 0;
        auto it_zero = lower_bound(partial_zero[c + 1 - a_count].begin(), partial_zero[c + 1 - a_count].end(), -act);
        if (it_zero != partial_zero[c + 1 - a_count].end()) {
