import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 66;
    static int r, c, n;
    static String s;
    static long[][] comb = new long[MAXN][MAXN];
    static int[] cnt_a = new int[MAXN], cnt_b = new int[MAXN];
    static List<Long>[] partial = new ArrayList[MAXN], partial_zero = new ArrayList[MAXN];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        r = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        s = br.readLine();
        n = 2 * (r + c);
        for (int i = 0; i <= c + 1; i++) {
            partial[i] = new ArrayList<>();
            partial_zero[i] = new ArrayList<>();
        }
        precompute_combinations();
        for (int i = 1; i <= n; i++) {
            cnt_a[i] = cnt_a[i - 1] + (s.charAt(i - 1) == 'A' ? 1 : 0);
            cnt_b[i] = cnt_b[i - 1] + (s.charAt(i - 1) == 'B' ? 1 : 0);
        }
        process_second_part();
        long result = solve_first_part();
        System.out.println(result);
    }

    static void precompute_combinations() {
        for (int i = 0; i <= n; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }
    }

    static long calculate_differences(int conf, int a_before, int b_before) {
        long total_diff = 0;
        for (int i = 0; i <= c; i++) {
            if ((conf & (1 << i)) != 0) {
                b_before++;
                long aux1 = comb[b_before - 1][r - 1];
                long aux2 = comb[n - b_before][r] - comb[a_before][r];
                total_diff -= aux1 * aux2;
            } else {
                a_before++;
                long aux1 = comb[a_before - 1][r - 1];
                long aux2 = comb[n - a_before][r] - comb[b_before][r];
                total_diff += aux1 * aux2;
            }
        }
        return total_diff;
    }

    static boolean validate_conf(int conf) {
        for (int i = 0; i <= c; i++) {
            char ch = s.charAt(2 * r + c + i);
            if (ch == 'A' && ((conf >> i) & 1) == 1) return false;
            if (ch == 'B' && ((conf >> i) & 1) == 0) return false;
        }
        return true;
    }

    static void process_second_part() {
        int total_conf = 1 << (c + 1);
        for (int conf = 0; conf < total_conf; conf++) {
            int b_count = Integer.bitCount(conf);
            int a_count = c + 1 - b_count;
            if (validate_conf(conf))
                partial[a_count].add(calculate_differences(conf, r + c - a_count, r + c - b_count));
            else
                partial_zero[a_count].add(calculate_differences(conf, r + c - a_count, r + c - b_count));
        }
        for (int i = 0; i <= c + 1; i++) {
            Collections.sort(partial[i]);
            Collections.sort(partial_zero[i]);
        }
    }

    static long get_coefficient(int conf) {
        int i;
        for (i = 0; i <= c; i++) {
            if ((((conf >> i) & 1) != (conf & 1))) break;
        }
        for (int j = i; j <= c; j++) {
            if (s.charAt(2 * r - 1 + j) == 'A' && (((conf >> j) & 1) == 1)) return 0;
            if (s.charAt(2 * r - 1 + j) == 'B' && (((conf >> j) & 1) == 0)) return 0;
        }
        int setA = r - 1 + (((conf & 1) == 0) ? i : 0);
        int setB = r - 1 + (((conf & 1) == 1) ? i : 0);
        if (setA < cnt_a[2 * r - 2 + i]) return 0;
        if (setB < cnt_b[2 * r - 2 + i]) return 0;
        int total = setA + setB - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i];
        return comb[total][setA - cnt_a[2 * r - 2 + i]];
    }

    static void update_answer(long[] answer, long[] current) {
        if (current[0] < 0) current[0] = -current[0];
        if (answer[0] > current[0]) {
            answer[0] = current[0];
            answer[1] = current[1];
        } else if (answer[0] == current[0]) {
            answer[1] += current[1];
        }
    }

    static long count_occurrences(List<Long> data, long val) {
        int lower = lowerBound(data, val);
        int upper = upperBound(data, val);
        return upper - lower;
    }

    static int lowerBound(List<Long> list, long val) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= val) high = mid;
            else low = mid + 1;
        }
        return low;
    }

    static int upperBound(List<Long> list, long val) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) > val) high = mid;
            else low = mid + 1;
        }
        return low;
    }

    static long solve_first_part() {
        int total_conf = 1 << (c + 1);
        long[] answer = {Long.MAX_VALUE, 0};
        for (int conf = 0; conf < total_conf; conf++) {
            int b_count = Integer.bitCount(conf);
            int a_count = c + 1 - b_count;
            long act = calculate_differences(conf, r - 1, r - 1);
            long coef = get_coefficient(conf);
            int idx = lowerBound(partial[c + 1 - a_count], -act);
            if (idx < partial[c + 1 - a_count].size()) {
                long val = partial[c + 1 - a_count].get(idx) + act;
                if (Math.abs(val) <= answer[0]) {
                    long count_coef = count_occurrences(partial[c + 1 - a_count], partial[c + 1 - a_count].get(idx));
                    update_answer(answer, new long[]{Math.abs(val), coef * count_coef});
                }
            }
            if (idx > 0) {
                long val = partial[c + 1 - a_count].get(idx - 1) + act;
                if (Math.abs(val) <= answer[0]) {
                    long count_coef = count_occurrences(partial[c + 1 - a_count], partial[c + 1 - a_count].get(idx - 1));
                    update_answer(answer, new long[]{Math.abs(val), coef * count_coef});
                }
            }
            // Zero coefficient branch
            long zero_coef = 0;
            int idx_zero = lowerBound(partial_zero[c + 1 - a_count], -act);
            if (idx_zero < partial_zero[c + 1 - a_count].size()) {
                long val = partial_zero[c + 1 - a_count].get(idx_zero) + act;
                long count_coef = count_occurrences(partial[c + 1 - a_count], partial_zero[c + 1 - a_count].get(idx_zero));
                if (Math.abs(val) <= answer[0]) {
                    update_answer(answer, new long[]{Math.abs(val), zero_coef * count_coef});
                }
            }
            if (idx_zero > 0) {
                long val = partial_zero[c + 1 - a_count].get(idx_zero - 1) + act;
                long count_coef = count_occurrences(partial[c + 1 - a_count], partial_zero[c + 1 - a_count].get(idx_zero - 1));
                if (Math.abs(val) <= answer[0]) {
                    update_answer(answer, new long[]{Math.abs(val), zero_coef * count_coef});
                }
            }
        }
        return answer[1];
    }
}
